with open('/workdir/data/books.json', 'r') as f:
    books_raw = f.read()

def fix_json_content(raw_text):
    lines = raw_text.splitlines()
    result_lines = []
    for i in range(len(lines)):
        line = lines[i]
        needs_comma_after = False
        if line.rstrip().endswith('}') and i + 1 < len(lines) and lines[i+1].lstrip().startswith('{'):
            needs_comma_after = True
        if needs_comma_after:
            result_lines.append(line.rstrip() + ',')
        else:
            result_lines.append(line)
        if i + 1 < len(lines):
            result_lines.append(lines[i+1])
    return '\n'.join(result_lines)

